const item = $input.first();
const bin = item.binary || {};
const keys = Object.keys(bin).sort();
const j = item.json || {};

if (keys.length < 2) {
  throw new Error('Two files are required. Only ' + keys.length + ' came through - please upload both exports.');
}

return [{
  json: {
    subject: j['What are you reconciling'] || 'this reconciliation',
    keyColumn: String(j['Column that links the two files'] || '').trim(),
    amountColumn: String(j['Column holding the amount'] || '').trim(),
    fileAField: keys[0],
    fileBField: keys[1],
    fileAName: (bin[keys[0]] || {}).fileName || 'File A',
    fileBName: (bin[keys[1]] || {}).fileName || 'File B'
  },
  binary: item.binary
}];

const cfg = $('Sort Out the Two Files').first().json;
const keyCol = cfg.keyColumn;
const amtCol = cfg.amountColumn;

const num = function (v) {
  const n = parseFloat(String(v === undefined || v === null ? '' : v).replace(/[^0-9.-]/g, ''));
  return isNaN(n) ? 0 : n;
};
const pick = function (row, col) {
  if (row[col] !== undefined) return row[col];
  const alt = Object.keys(row).filter(function (k) { return k.toLowerCase() === String(col).toLowerCase(); })[0];
  return alt ? row[alt] : '';
};

const buckets = { 'Only in the source of truth': [], 'Agrees': [], 'Values disagree': [], 'Only in your records': [] };
const rows = [];

for (const it of $input.all()) {
  const r = it.json || {};
  const b = r.bucket || 'Agrees';
  if (!buckets[b]) buckets[b] = [];
  const key = String(pick(r, keyCol) || '');
  const amount = num(pick(r, amtCol));
  const entry = { key: key, amount: amount, bucket: b, raw: r };
  buckets[b].push(entry);
  rows.push(entry);
}

const total = function (b) { return Math.round((buckets[b] || []).reduce(function (a, x) { return a + x.amount; }, 0) * 100) / 100; };
const counts = {
  missing: (buckets['Only in the source of truth'] || []).length,
  agrees: (buckets['Agrees'] || []).length,
  disagree: (buckets['Values disagree'] || []).length,
  extra: (buckets['Only in your records'] || []).length
};
const gap = Math.round((total('Only in the source of truth') - total('Only in your records')) * 100) / 100;
const problems = counts.missing + counts.disagree + counts.extra;

const sampleOf = function (b, n) {
  return (buckets[b] || []).slice(0, n).map(function (x) { return x.key + ' (' + x.amount + ')'; }).join(', ');
};

return [{ json: {
  subject: cfg.subject,
  keyColumn: keyCol,
  amountColumn: amtCol,
  fileAName: cfg.fileAName,
  fileBName: cfg.fileBName,
  counts: counts,
  problems: problems,
  balanced: problems === 0,
  totalMissing: total('Only in the source of truth'),
  totalExtra: total('Only in your records'),
  netGap: gap,
  rowsCompared: rows.length,
  sampleMissing: sampleOf('Only in the source of truth', 12),
  sampleDisagree: sampleOf('Values disagree', 12),
  sampleExtra: sampleOf('Only in your records', 12),
  allRows: rows
} }];

parameters.text:
=Two exports that should agree do not. Do not list the individual differences - the workbook already does that. Explain the systemic reasons they drifted apart, so the person can fix the cause rather than tick off rows.

Reconciling: {{ $json.subject }}
File A (source of truth): {{ $json.fileAName }} | File B (your records): {{ $json.fileBName }}
Matched on: {{ $json.keyColumn }} | Amount column: {{ $json.amountColumn }}

Rows compared: {{ $json.rowsCompared }}
Agree: {{ $json.counts.agrees }}
In A but not B: {{ $json.counts.missing }} totalling {{ $json.totalMissing }}
In B but not A: {{ $json.counts.extra }} totalling {{ $json.totalExtra }}
Same reference, different amount: {{ $json.counts.disagree }}
Net gap: {{ $json.netGap }}

Examples in A only: {{ $json.sampleMissing }}
Examples that disagree: {{ $json.sampleDisagree }}
Examples in B only: {{ $json.sampleExtra }}

The usual culprits in reconciliations like this are: a cut-off or timing difference between when the two exports were taken; fees, commission or tax deducted on one side only; currency conversion or rounding; refunds, credit notes or reversals netted on one side; duplicated entries; and reference format drift where the same item is written differently in each system, which shows up as an item missing from both sides at once.

Look at the shape of the numbers before deciding. If the count in A only and the count in B only are similar and the amounts pair up, suspect reference format drift rather than missing records. If the disagreements are all small and in the same direction, suspect fees or rounding. Give each cause a rough share of the gap and the single quickest check that would confirm or kill it. Set materiality to clean, minor or material - material means a person should not close the period on this. Put anything the evidence does not support into do_not_conclude.

