const a = $('Assemble the Reconciliation').first().json;
const d = $json.output || {};
const out = [];

out.push({ 'Bucket': 'SUMMARY', 'Reference': a.subject, 'Amount': '', 'Detail': d.headline || '', 'Action': 'Materiality: ' + (d.materiality || 'unknown') });
out.push({ 'Bucket': 'SUMMARY', 'Reference': 'Rows compared', 'Amount': a.rowsCompared, 'Detail': a.counts.agrees + ' agree, ' + a.counts.disagree + ' disagree, ' + a.counts.missing + ' only in source, ' + a.counts.extra + ' only in yours', 'Action': '' });
out.push({ 'Bucket': 'SUMMARY', 'Reference': 'Net gap', 'Amount': a.netGap, 'Detail': 'Source-only total ' + a.totalMissing + ' minus yours-only total ' + a.totalExtra, 'Action': '' });

for (const c of (Array.isArray(d.likely_causes) ? d.likely_causes : [])) {
  out.push({ 'Bucket': 'LIKELY CAUSE', 'Reference': c.cause || '', 'Amount': c.share_of_gap || '', 'Detail': c.evidence || '', 'Action': c.check_first || '' });
}
for (const s of (Array.isArray(d.what_to_do_now) ? d.what_to_do_now : [])) {
  out.push({ 'Bucket': 'DO NEXT', 'Reference': '', 'Amount': '', 'Detail': String(s), 'Action': '' });
}
for (const s of (Array.isArray(d.do_not_conclude) ? d.do_not_conclude : [])) {
  out.push({ 'Bucket': 'DO NOT CONCLUDE', 'Reference': '', 'Amount': '', 'Detail': String(s), 'Action': '' });
}

const order = ['Values disagree', 'Only in the source of truth', 'Only in your records', 'Agrees'];
for (const b of order) {
  const rows = a.allRows.filter(function (r) { return r.bucket === b; });
  if (!rows.length) continue;
  out.push({ 'Bucket': b.toUpperCase(), 'Reference': rows.length + ' row(s)', 'Amount': '', 'Detail': '', 'Action': '' });
  for (const r of rows) {
    out.push({ 'Bucket': b, 'Reference': r.key, 'Amount': r.amount, 'Detail': JSON.stringify(r.raw).slice(0, 400), 'Action': b === 'Agrees' ? '' : 'Investigate' });
  }
}

return out.map(function (r) { return { json: r }; });

